    (128, 'Y', 21, 'demand_impact', 'LNG 수요 영향 규모', 'direct', (SELECT `model_param_id` FROM `tmm_mi_model_param_m` WHERE `parameter_name` = 'User-Adjusted Gas Demand' AND `del_yn` = 'N'), '수요 영향분 직접 조정(또는 PMI 강도로 반영)', 'system', 'system', 'N')
ON DUPLICATE KEY UPDATE
    `use_yn` = VALUES(`use_yn`),
    `event_type_l2_id` = VALUES(`event_type_l2_id`),
    `dimension_key` = VALUES(`dimension_key`),
    `dimension_label` = VALUES(`dimension_label`),
    `mapping_method` = VALUES(`mapping_method`),
    `model_param_id` = VALUES(`model_param_id`),
    `comment` = VALUES(`comment`),
    `mod_usr_logn_id` = 'system',
    `del_yn` = 'N';

-- Validation queries
SELECT COUNT(*) AS model_param_count FROM `tmm_mi_model_param_m` WHERE `del_yn` = 'N';
SELECT COUNT(*) AS model_param_dimension_map_count FROM `tmm_mi_model_param_dimension_map` WHERE `del_yn` = 'N';
SELECT COUNT(*) AS direct_or_routing_without_model_param_count
FROM `tmm_mi_model_param_dimension_map`
WHERE `del_yn` = 'N'
  AND `use_yn` = 'Y'
  AND `mapping_method` IN ('direct', 'routing')
  AND `model_param_id` IS NULL;

COMMIT;
